{%- liquid
  assign mf_vd = product.metafields.custom.volume_discounts
  assign vd = '{"tiers":[]}'

  if mf_vd != blank and mf_vd.value != blank
    if mf_vd.type == 'json'
      assign vd = mf_vd.value | json
    else
      assign vd = mf_vd.value
    endif
  endif
-%}

<style>
  :root{
    --rt-blue:  #003878;
    --rt-price: #FF7300;
    --rt-green: #74C200;
    --rt-radius: 8px;
  }

  [data-rt-dynamic-price]{
    margin: 0;
    padding: 0;
    border: none;
    border-radius: var(--rt-radius);
    background: transparent;
    max-width: 520px;
  }

  [data-rt-dynamic-price][hidden]{
    display: none !important;
  }

  [data-rt-dynamic-price] [data-rt-excl]{
    color: var(--rt-price);
    font-weight: 800;
    font-size: 24px;
    line-height: 1.05;
    margin: 0;
  }

  [data-rt-dynamic-price] [data-rt-incl]{
    color: var(--rt-blue);
    font-weight: 600;
    font-size: 14px;
    line-height: 1.1;
    opacity: .9;
    margin: 6px 0 0;
  }

  [data-rt-dynamic-price] [data-rt-save]{
    color: var(--rt-green);
    font-weight: 700;
    font-size: 14px;
    line-height: 1.2;
    margin: 8px 0 0;
  }

  @media (max-width: 767px){
    [data-rt-dynamic-price]{ max-width: 100%; }
  }
</style>

<div data-rt-dynamic-price hidden>
  <div data-rt-excl></div>
  <div data-rt-incl></div>
  <div data-rt-save></div>
</div>

<script type="application/json" data-rt-volume-tiers>{{ vd }}</script>

<script type="application/json" data-rt-variant-prices>
[
  {%- for v in product.variants -%}
    {"id":{{ v.id }},"price":{{ v.price }} }{%- unless forloop.last -%},{%- endunless -%}
  {%- endfor -%}
]
</script>

<script>
(() => {
  const ROOT = document.querySelector('[data-rt-dynamic-price]');
  if (!ROOT) return;
  if (ROOT.dataset.rtInited === '1') return;
  ROOT.dataset.rtInited = '1';

  const VAT_RATE = 0.21;
  const PRICE_INCLUDES_VAT = true;

  // Hide block if base unit price is 0 or 1 cent (0.01)
  const HIDE_IF_BASE_UNIT_CENTS_LTE = 1;

  const moneyFormat = {{ shop.money_format | json }};
  const localeISO   = {{ request.locale.iso_code | json }};
  const currencyISO = {{ cart.currency.iso_code | default: shop.currency | json }};

  // === tiers ===
  let tiers = [];
  try {
    const rawText = document.querySelector('script[data-rt-volume-tiers]')?.textContent || '{"tiers":[]}';
    let obj = JSON.parse(rawText);
    if (typeof obj === 'string') obj = JSON.parse(obj);
    tiers = Array.isArray(obj?.tiers) ? obj.tiers : [];
  } catch(e) {}

  const normDisc = (v) => {
    let n = Number(v);
    if (!Number.isFinite(n)) return 0;
    if (n > 1) n = n / 100;
    return Math.max(0, Math.min(0.99, n));
  };

  tiers = tiers
    .map(t => ({ min: Number(t.min), discount: normDisc(t.discount) }))
    .filter(t => Number.isFinite(t.min) && t.min >= 2 && t.discount > 0)
    .sort((a,b) => a.min - b.min);

  // === variant prices ===
  let variantPrices = [];
  try {
    variantPrices = JSON.parse(document.querySelector('script[data-rt-variant-prices]')?.textContent || '[]');
  } catch(e) {}
  const priceMap = new Map(variantPrices.map(p => [Number(p.id), Number(p.price)]));

  function formatMoneyCents(cents){
    const c = Math.round(Number(cents) || 0);
    if (window.Shopify && typeof Shopify.formatMoney === 'function') {
      return Shopify.formatMoney(c, moneyFormat);
    }
    return new Intl.NumberFormat(localeISO || undefined, { style:'currency', currency: currencyISO || 'EUR' })
      .format(c / 100);
  }

  function isVisible(el){
    if (!el) return false;
    if (el.closest('[hidden], [aria-hidden="true"]')) return false;
    return !!(el.offsetParent || el.getClientRects().length);
  }

  function getActiveAddToCartForm(){
    const forms = Array.from(document.querySelectorAll('form[action*="/cart/add"], form[action^="/cart/add"]'));
    if (!forms.length) return document.querySelector('form') || null;
    const visible = forms.filter(isVisible);
    return (visible[0] || forms[0] || null);
  }

  function getIdInput(){
    const form = getActiveAddToCartForm();
    return form?.querySelector('input[name="id"]') || document.querySelector('input[name="id"]');
  }

  function getQtyInput(){
    const form = getActiveAddToCartForm();
    if (!form) return null;
    return (
      form.querySelector('input[name="quantity"]') ||
      form.querySelector('quantity-input input') ||
      form.querySelector('input[type="number"]')
    );
  }

  function getQty(){
    const el = getQtyInput();
    const q = Number(el?.value);
    return (Number.isFinite(q) && q > 0) ? Math.floor(q) : 1;
  }

  function getVariantId(){
    const idEl = getIdInput();
    const fromHidden = Number(idEl?.value);
    if (Number.isFinite(fromHidden)) return fromHidden;

    // fallback (alleen als nodig)
    const picked =
      document.querySelector('input[type="radio"][data-variant-id]:checked') ||
      Array.from(document.querySelectorAll('input[type="radio"][data-variant-id]'))
        .find(el => el.getAttribute('data-current-checked') === 'true');

    const fromPicker = Number(picked?.getAttribute('data-variant-id'));
    if (Number.isFinite(fromPicker)) return fromPicker;

    const v = new URLSearchParams(location.search).get('variant');
    const fromUrl = Number(v);
    return Number.isFinite(fromUrl) ? fromUrl : null;
  }

  function discountForQty(qty){
    let d = 0;
    for (const t of tiers) if (qty >= t.min) d = t.discount;
    return d;
  }

  function setHidden(isHidden){
    if (isHidden) {
      ROOT.setAttribute('hidden', '');
      ROOT.querySelector('[data-rt-excl]').textContent = '';
      ROOT.querySelector('[data-rt-incl]').textContent = '';
      ROOT.querySelector('[data-rt-save]').textContent = '';
    } else {
      ROOT.removeAttribute('hidden');
    }
  }

  let raf = 0;
  function scheduleRender(){
    if (raf) cancelAnimationFrame(raf);
    raf = requestAnimationFrame(() => { raf = 0; render(); });

    // Horizon/sticky/drawer timing edge-cases
    setTimeout(render, 50);
    setTimeout(render, 200);
    setTimeout(render, 500);
  }

  function render(){
    const vid = getVariantId();
    if (!vid) { setHidden(true); return; }

    const baseCentsRaw = priceMap.get(vid);
    if (!Number.isFinite(baseCentsRaw)) { setHidden(true); return; }

    // Hide entire block if base unit price is 0 or 1 cent
    if (baseCentsRaw <= HIDE_IF_BASE_UNIT_CENTS_LTE) { setHidden(true); return; }

    const qty = getQty();
    const discount = discountForQty(qty);

    const baseUnitIncl = PRICE_INCLUDES_VAT ? baseCentsRaw : Math.round(baseCentsRaw * (1 + VAT_RATE));
    const unitIncl = Math.round(baseUnitIncl * (1 - discount));

    const totalIncl = unitIncl * qty;
    const totalExcl = Math.round(totalIncl / (1 + VAT_RATE));
    const savings   = (baseUnitIncl * qty) - totalIncl;

    setHidden(false);

    ROOT.querySelector('[data-rt-excl]').textContent = `${formatMoneyCents(totalExcl)} (excl. BTW)`;
    ROOT.querySelector('[data-rt-incl]').textContent = `${formatMoneyCents(totalIncl)} (incl. BTW)`;
    ROOT.querySelector('[data-rt-save]').textContent = discount > 0 ? `- ${formatMoneyCents(savings)}` : '';
  }

  // ===== Observer-based (no polling) =====
  let observedIdEl = null;
  let idObserver = null;

  function observeIdInput(){
    const idEl = getIdInput();
    if (!idEl || idEl === observedIdEl) return;

    if (idObserver) { try { idObserver.disconnect(); } catch(e) {} }
    observedIdEl = idEl;

    // When theme fires events
    idEl.addEventListener('change', scheduleRender, true);
    idEl.addEventListener('input',  scheduleRender, true);

    // When theme mutates attribute/value
    idObserver = new MutationObserver(() => scheduleRender());
    try {
      idObserver.observe(idEl, { attributes: true, attributeFilter: ['value'] });
    } catch(e) {}
  }

  // Watch for form swaps / drawers / sticky ATC being injected
  const formSwapObserver = new MutationObserver(() => observeIdInput());
  try {
    formSwapObserver.observe(document.documentElement, { childList: true, subtree: true });
  } catch(e) {}

  // Qty updates: render (price depends on qty)
  document.addEventListener('input', (e) => {
    if (e.target && e.target.matches('[name="quantity"], quantity-input input, input[type="number"]')) {
      scheduleRender();
    }
  }, true);

  document.addEventListener('change', (e) => {
    if (
      e.target?.matches?.('input[type="radio"]') ||
      e.target?.matches?.('select') ||
      e.target?.matches?.('[name="id"]')
    ) {
      scheduleRender();
    }
  }, true);

  document.addEventListener('click', (e) => {
    if (
      e.target?.closest?.('label.variant-option__button-label') ||
      e.target?.closest?.('[data-option-value]') ||
      e.target?.closest?.('variant-selects') ||
      e.target?.closest?.('variant-radios')
    ) {
      scheduleRender();
    }
  }, true);

  // init
  observeIdInput();
  render();
})();
</script>

{%- liquid
  assign threshold_eur = 100
  assign cutoff_hour = 17

  assign mf_vd = product.metafields.custom.volume_discounts
  assign vd = '{"tiers":[]}'

  if mf_vd != blank and mf_vd.value != blank
    if mf_vd.type == 'json'
      assign vd = mf_vd.value | json
    else
      assign vd = mf_vd.value | strip
    endif
  endif
-%}

<div class="rt-shipfree"
     data-rt-shipfree
     data-threshold-eur="{{ threshold_eur }}"
     data-cutoff-hour="{{ cutoff_hour }}"
     data-timezone="Europe/Amsterdam"
     data-default-variant-id="{{ product.selected_or_first_available_variant.id }}">
  <span class="rt-shipfree__text">Gratis verzending vanaf €{{ threshold_eur }}.</span>

  <script type="application/json" data-rt-volume-tiers>{{ vd }}</script>

  <script type="application/json" data-rt-variant-prices>
  [
    {%- for v in product.variants -%}
      {"id":{{ v.id }},"price":{{ v.price }} }{%- unless forloop.last -%},{%- endunless -%}
    {%- endfor -%}
  ]
  </script>

  <style>
    .rt-shipfree{
      display:inline-flex;
      align-items:flex-start;
      gap:6px;

      width:fit-content;
      max-width:100%;

      padding:4px 8px;
      border-radius:8px;

      background:#EBF4FF;
      color:#002B5C;

      font-size:14px;
      line-height:1.2;

      font-family: Overpass, var(--font-body--family, inherit), Arial, sans-serif;
      font-weight:500;

      margin:0;
    }

    /* ✅ altijd 2 regels mogelijk (geen nowrap) */
    .rt-shipfree__text{
      white-space:normal;
    }

    .rt-shipfree__free{
      color:#74C200;
      font-weight:700;
    }

    /* Mobiel: max 2 regels + netjes afbreken (werkt ook op desktop als tekst te lang is) */
    .rt-shipfree__text{
      overflow-wrap:anywhere;
      word-break:normal;
    }
  </style>

  <script>
  (function(){
    var root = (document.currentScript && document.currentScript.closest)
      ? document.currentScript.closest('[data-rt-shipfree]')
      : null;
    if(!root) root = document.querySelector('[data-rt-shipfree]');
    if(!root) return;
    if(root.dataset.rtInited === '1') return;
    root.dataset.rtInited = '1';

    var thresholdEur = Number(root.getAttribute('data-threshold-eur') || 100);
    var cutoffHour   = Number(root.getAttribute('data-cutoff-hour') || 17);
    var timeZone     = root.getAttribute('data-timezone') || 'Europe/Amsterdam';
    var defaultVid   = Number(root.getAttribute('data-default-variant-id')) || null;

    var VAT_RATE = 0.21;
    var PRICE_INCLUDES_VAT = true;
    var THRESHOLD_INCLUDES_VAT = true;

    var textEl = root.querySelector('.rt-shipfree__text');
    if(!textEl) return;

    var thresholdCents = Math.round(thresholdEur * 100);

    // tiers
    var tiers = [];
    try{
      var raw = root.querySelector('script[data-rt-volume-tiers]').textContent || '{"tiers":[]}';
      var obj = JSON.parse(raw);
      if(typeof obj === 'string') obj = JSON.parse(obj);
      tiers = Array.isArray(obj.tiers) ? obj.tiers : [];
    }catch(e){ tiers = []; }

    function normDisc(v){
      var n = Number(v);
      if(!isFinite(n)) return 0;
      if(n > 1) n = n / 100;
      if(n < 0) n = 0;
      if(n > 0.99) n = 0.99;
      return n;
    }

    tiers = tiers
      .map(function(t){ return { min: Number(t.min), discount: normDisc(t.discount) }; })
      .filter(function(t){ return isFinite(t.min) && t.min >= 2 && t.discount > 0; })
      .sort(function(a,b){ return a.min - b.min; });

    function discountForQty(qty){
      var d = 0;
      for(var i=0;i<tiers.length;i++){
        if(qty >= tiers[i].min) d = tiers[i].discount;
      }
      return d;
    }

    // variant prices
    var priceMap = new Map();
    try{
      var vp = JSON.parse(root.querySelector('script[data-rt-variant-prices]').textContent || '[]');
      for(var j=0;j<vp.length;j++){
        priceMap.set(Number(vp[j].id), Number(vp[j].price));
      }
    }catch(e){}

    function isVisible(el){
      if(!el) return false;
      if(el.closest('[hidden], [aria-hidden="true"]')) return false;
      return !!(el.offsetParent || el.getClientRects().length);
    }

    function getActiveAddToCartForm(){
      var forms = Array.prototype.slice.call(document.querySelectorAll('form[action*="/cart/add"], form[action^="/cart/add"]'));
      if(!forms.length) return document.querySelector('form') || null;
      var visible = forms.filter(isVisible);
      return visible[0] || forms[0] || null;
    }

    function getQty(){
      var form = getActiveAddToCartForm();
      var el = form && (form.querySelector('input[name="quantity"]') || form.querySelector('quantity-input input') || form.querySelector('input[type="number"]'));
      var q = Number(el && el.value);
      return (isFinite(q) && q > 0) ? Math.floor(q) : 1;
    }

    function getVariantId(){
      var form = getActiveAddToCartForm();
      var idEl = form && form.querySelector('[name="id"]');
      var fromHidden = Number(idEl && idEl.value);
      if(isFinite(fromHidden) && fromHidden > 0) return fromHidden;

      var picked = document.querySelector('input[type="radio"][data-variant-id]:checked');
      var fromPicker = Number(picked && picked.getAttribute('data-variant-id'));
      if(isFinite(fromPicker) && fromPicker > 0) return fromPicker;

      var v = new URLSearchParams(location.search).get('variant');
      var fromUrl = Number(v);
      if(isFinite(fromUrl) && fromUrl > 0) return fromUrl;

      return defaultVid;
    }

    function getTimeInfo(){
      var now = new Date();

      var weekday = new Intl.DateTimeFormat('en-US', { timeZone: timeZone, weekday: 'short' }).format(now);
      var parts = new Intl.DateTimeFormat('en-GB', { timeZone: timeZone, hour:'2-digit', minute:'2-digit', hour12:false }).formatToParts(now);
      var hourPart = parts.filter(function(p){ return p.type === 'hour'; })[0];
      var hour = Number(hourPart && hourPart.value || 0);

      var isWeekend = (weekday === 'Sat' || weekday === 'Sun');
      var beforeCutoff = (hour < cutoffHour);
      return { isWeekend: isWeekend, beforeCutoff: beforeCutoff };
    }

    // ✅ altijd 2 regels zoals jij wilt
    function setMessage(eligible, todayWindow){
      var FREE = '<span class="rt-shipfree__free">GRATIS</span>';

      if (eligible){
        if (todayWindow){
          textEl.innerHTML =
            '<span class="rt-shipfree__line1">Bestel je nu,</span><br>' +
            '<span class="rt-shipfree__line2">dan wordt je bestelling vandaag ' + FREE + ' verzonden.</span>';
        } else {
          textEl.innerHTML =
            '<span class="rt-shipfree__line1">Elke werkdag vóór ' + cutoffHour + ':00</span><br>' +
            '<span class="rt-shipfree__line2">' + FREE + ' verzonden.</span>';
        }
        return;
      }

      textEl.innerHTML =
        '<span class="rt-shipfree__line1">Gratis verzending </span>' +
        '<span class="rt-shipfree__line2">vanaf €' + thresholdEur + '.</span>';
    }

    function computeTotals(variantId, qty){
      var baseRaw = priceMap.get(Number(variantId));
      if(!isFinite(baseRaw)) return null;

      var disc = discountForQty(qty);
      var unitIncl = PRICE_INCLUDES_VAT ? baseRaw : Math.round(baseRaw * (1 + VAT_RATE));
      var unitInclDiscounted = Math.round(unitIncl * (1 - disc));

      var totalIncl = unitInclDiscounted * qty;
      var totalExcl = Math.round(totalIncl / (1 + VAT_RATE));

      return { totalIncl: totalIncl, totalExcl: totalExcl };
    }

    function render(){
      var t = getTimeInfo();
      var todayWindow = (!t.isWeekend && t.beforeCutoff);

      var vid = getVariantId();
      var qty = getQty();

      if(!vid){
        setMessage(false, todayWindow);
        return;
      }

      var totals = computeTotals(vid, qty);
      if(!totals){
        setMessage(false, todayWindow);
        return;
      }

      var compareTotal = THRESHOLD_INCLUDES_VAT ? totals.totalIncl : totals.totalExcl;
      var eligible = (compareTotal >= thresholdCents);

      setMessage(eligible, todayWindow);
    }

    var lastVid = null, lastQty = null;

    function tick(){
      var vid = getVariantId();
      var qty = getQty();
      if(vid !== lastVid || qty !== lastQty){
        lastVid = vid;
        lastQty = qty;
        render();
      }
    }

    render();
    setInterval(tick, 250);

    document.addEventListener('change', function(){ setTimeout(render, 20); }, true);
    document.addEventListener('input',  function(){ setTimeout(render, 20); }, true);
    document.addEventListener('click',  function(){ setTimeout(render, 50); }, true);
  })();
  </script>
</div>

{%- assign mf_vd = product.metafields.custom.volume_discounts -%}
{%- assign vd = '' -%}

{%- if mf_vd != blank and mf_vd.value != blank -%}
  {%- if mf_vd.type == 'json' -%}
    {%- assign vd = mf_vd.value | json -%}
  {%- else -%}
    {%- assign vd = mf_vd.value | default: '' | strip -%}
  {%- endif -%}
{%- endif -%}

{%- if vd != blank -%}
  <div data-rt-discount-table-wrap hidden>
    <div data-rt-discount-table></div>

    <script type="application/json" data-rt-volume-tiers>{{ vd }}</script>

    <script type="application/json" data-rt-variant-prices>
    [
      {%- for v in product.variants -%}
        {"id":{{ v.id }},"price":{{ v.price }} }{%- unless forloop.last -%},{%- endunless -%}
      {%- endfor -%}
    ]
    </script>

    <style>
      :root{
        --rt-blue: #003878;
        --rt-orange: #FF7300;
        --rt-green: #74C200;
        --rt-grey: #EDF0F2;
        --rt-border: rgba(160,178,201,.55);
        --rt-text: rgba(0,0,0,.78);
      }

      .discount-table{
        width: 100%;
        max-width: 720px;
        margin-top: 0px;

        border-collapse: separate;
        border-spacing: 0;
        table-layout: fixed;

        border: 1px solid var(--rt-border);
        border-radius: 0;
        overflow: hidden;
        background: #fff;
      }
      @media (max-width: 767px){ .discount-table{ max-width: 100%; } }

      .discount-table th{
        background: #fff;
        color: var(--rt-blue);
        font-weight: 700;
        padding: 10px 8px;
        text-align: center;
        vertical-align: middle;
        border-bottom: 1px solid var(--rt-border);
        font-size: 14px;
      }
      .discount-table th .subtext{
        display: block;
        margin-top: 2px;
        font-size: 12px;
        font-weight: 500;
        color: var(--rt-text);
      }

      .discount-table td{
        padding: 10px 8px;
        text-align: center;
        vertical-align: middle;
        font-size: 13px;
        font-weight: 500;
        color: var(--rt-text);
        border-bottom: 1px solid var(--rt-border);
        background: #fff;
      }
      .discount-table tbody tr:nth-child(even) td{ background: #EDF0F2; }

      .discount-table td.korting{
        color: var(--rt-green);
        font-weight: 700;
      }

      .discount-table tbody tr[data-min-qty]{ cursor: pointer; }

      .discount-table tbody tr[data-min-qty]:not(.active-tier):hover td{ color: var(--rt-orange); }
      .discount-table tbody tr[data-min-qty]:not(.active-tier):hover td.korting{ color: var(--rt-green); }

      .discount-table tbody tr.active-tier td{
        border-top: 2px solid var(--rt-blue);
        border-bottom: 2px solid var(--rt-blue);
      }
      .discount-table tbody tr.active-tier td:first-child{ border-left: 2px solid var(--rt-blue); }
      .discount-table tbody tr.active-tier td:last-child{  border-right: 2px solid var(--rt-blue); }

      .discount-table tbody tr:last-child td{ border-bottom: none; }
      .discount-table tbody tr:last-child.active-tier td{ border-bottom: 2px solid var(--rt-blue); }
    </style>

    <script>
      (() => {
        const WRAP = document.currentScript && document.currentScript.closest('[data-rt-discount-table-wrap]');
        const OUT  = WRAP && WRAP.querySelector('[data-rt-discount-table]');
        if (!WRAP || !OUT) return;
        if (WRAP.dataset.rtInited === '1') return;
        WRAP.dataset.rtInited = '1';

        const VAT_RATE = 0.21;
        const PRICE_INCLUDES_VAT = true;

        const moneyFormat = {{ shop.money_format | json }};
        const localeISO   = {{ request.locale.iso_code | json }};
        const currencyISO = {{ cart.currency.iso_code | default: shop.currency | json }};

        // === tiers ===
        let tiers = [];
        try {
          const rawText = WRAP.querySelector('script[data-rt-volume-tiers]')?.textContent || '{}';
          let obj = JSON.parse(rawText);
          if (typeof obj === 'string') obj = JSON.parse(obj);
          tiers = Array.isArray(obj?.tiers) ? obj.tiers : [];
        } catch(e) {}

        const normDisc = (v) => {
          let n = Number(v);
          if (!Number.isFinite(n)) return 0;
          if (n > 1) n = n / 100;
          return Math.max(0, Math.min(0.99, n));
        };

        tiers = tiers
          .map(t => ({ min: Number(t.min), discount: normDisc(t.discount) }))
          .filter(t => Number.isFinite(t.min) && t.min >= 2 && t.discount > 0)
          .sort((a,b) => a.min - b.min);

        // ✅ Geen tiers = component bestaat niet (0 ruimte)
        if (!tiers.length) { WRAP.remove(); return; }

        // === variant prices ===
        let variantPrices = [];
        try {
          variantPrices = JSON.parse(WRAP.querySelector('script[data-rt-variant-prices]')?.textContent || '[]');
        } catch(e) {}
        const priceMap = new Map(variantPrices.map(p => [Number(p.id), Number(p.price)]));

        function formatMoneyCents(cents){
          const c = Math.round(Number(cents) || 0);
          if (window.Shopify && typeof Shopify.formatMoney === 'function') {
            return Shopify.formatMoney(c, moneyFormat);
          }
          return new Intl.NumberFormat(localeISO || undefined, { style:'currency', currency: currencyISO || 'EUR' })
            .format(c / 100);
        }

        function isVisible(el){
          if (!el) return false;
          if (el.closest('[hidden], [aria-hidden="true"]')) return false;
          return !!(el.offsetParent || el.getClientRects().length);
        }

        function getActiveAddToCartForm(){
          const forms = Array.from(document.querySelectorAll('form[action*="/cart/add"], form[action^="/cart/add"]'));
          if (!forms.length) return document.querySelector('form') || null;
          const visible = forms.filter(isVisible);
          return (visible[0] || forms[0] || null);
        }

        function getIdInput(){
          const form = getActiveAddToCartForm();
          return form?.querySelector('input[name="id"]') || document.querySelector('input[name="id"]');
        }

        function getQtyInput(){
          const form = getActiveAddToCartForm();
          if (!form) return null;
          return (
            form.querySelector('input[name="quantity"]') ||
            form.querySelector('quantity-input input') ||
            form.querySelector('input[type="number"]')
          );
        }

        function getQty(){
          const q = Number(getQtyInput()?.value);
          return (Number.isFinite(q) && q > 0) ? Math.floor(q) : 1;
        }

        function setQty(n){
          const el = getQtyInput();
          if (!el) return;
          el.value = String(n);
          el.dispatchEvent(new Event('input', { bubbles: true }));
          el.dispatchEvent(new Event('change', { bubbles: true }));
        }

        function getVariantId(){
          const idEl = getIdInput();
          const fromHidden = Number(idEl?.value);
          if (Number.isFinite(fromHidden)) return fromHidden;

          // fallback (alleen als nodig)
          const picked =
            document.querySelector('input[type="radio"][data-variant-id]:checked') ||
            Array.from(document.querySelectorAll('input[type="radio"][data-variant-id]'))
              .find(el => el.getAttribute('data-current-checked') === 'true');

          const fromPicker = Number(picked?.getAttribute('data-variant-id'));
          if (Number.isFinite(fromPicker)) return fromPicker;

          const v = new URLSearchParams(location.search).get('variant');
          const fromUrl = Number(v);
          return Number.isFinite(fromUrl) ? fromUrl : null;
        }

        function activeTierMinForQty(qty){
          let activeMin = 1;
          for (const t of tiers) if (qty >= t.min) activeMin = t.min;
          return activeMin;
        }

        function buildTableForUnit(unitInclCents){
          const unitIncl = Math.round(Number(unitInclCents) || 0);
          if (!Number.isFinite(unitIncl) || unitIncl <= 0) return false;

          const unitExcl = Math.round(unitIncl / (1 + VAT_RATE));

          let html = '';
          html += '<table class="discount-table" data-rt-table>';
          html += '<thead><tr>';
          html += '<th>Aantal<br><span class="subtext">stuks</span></th>';
          html += '<th>Prijs<br><span class="subtext">excl. BTW</span></th>';
          html += '<th>Prijs<br><span class="subtext">incl. BTW</span></th>';
          html += '<th>Korting</th>';
          html += '</tr></thead><tbody>';

          html += `
            <tr data-min-qty="1">
              <td>1</td>
              <td>${formatMoneyCents(unitExcl)}</td>
              <td>${formatMoneyCents(unitIncl)}</td>
              <td>-</td>
            </tr>
          `;

          for (const t of tiers) {
            const disc = t.discount;
            const tierUnitIncl = Math.round(unitIncl * (1 - disc));
            const tierUnitExcl = Math.round(tierUnitIncl / (1 + VAT_RATE));
            const pct = Math.round(disc * 100);

            html += `
              <tr data-min-qty="${t.min}">
                <td>${t.min}+</td>
                <td>${formatMoneyCents(tierUnitExcl)}</td>
                <td>${formatMoneyCents(tierUnitIncl)}</td>
                <td class="korting">${pct}%</td>
              </tr>
            `;
          }

          html += '</tbody></table>';
          OUT.innerHTML = html;
          return true;
        }

        function markActiveRow(){
          const table = OUT.querySelector('[data-rt-table]');
          if (!table) return;

          const qty = getQty();
          const activeMin = activeTierMinForQty(qty);

          table.querySelectorAll('tr').forEach(tr => tr.classList.remove('active-tier'));
          const activeRow = table.querySelector(`tr[data-min-qty="${activeMin}"]`);
          if (activeRow) activeRow.classList.add('active-tier');
        }

        let lastBuiltVid = null;

        function render(forceRebuild=false){
          const vid = getVariantId();

          // tijdens switch kan dit héél kort null zijn → verbergen, NIET verwijderen
          if (!vid) { WRAP.hidden = true; return; }

          const baseCentsRaw = priceMap.get(vid);
          if (!Number.isFinite(baseCentsRaw)) { WRAP.hidden = true; return; }

          const unitIncl = PRICE_INCLUDES_VAT ? baseCentsRaw : Math.round(baseCentsRaw * (1 + VAT_RATE));

          if (forceRebuild || vid !== lastBuiltVid) {
            const ok = buildTableForUnit(unitIncl);
            if (!ok) { WRAP.hidden = true; return; }
            lastBuiltVid = vid;
          }

          WRAP.hidden = false;
          markActiveRow();
        }

        OUT.addEventListener('click', (e) => {
          const tr = e.target.closest('tr[data-min-qty]');
          if (!tr) return;
          const min = Number(tr.getAttribute('data-min-qty'));
          if (Number.isFinite(min)) setQty(min);
        });

        // ===== Update scheduler (event-driven, no polling) =====
        let raf = 0;
        function scheduleVariantUpdate(){
          if (raf) cancelAnimationFrame(raf);
          raf = requestAnimationFrame(() => { raf = 0; render(true); });
          // Horizon/sticky/drawer: sometimes id updates slightly later
          setTimeout(() => render(true), 50);
          setTimeout(() => render(true), 200);
          setTimeout(() => render(true), 500);
        }

        function scheduleQtyUpdate(){
          if (raf) cancelAnimationFrame(raf);
          raf = requestAnimationFrame(() => { raf = 0; markActiveRow(); });
          setTimeout(markActiveRow, 0);
        }

        // ===== Bind to active form (and re-bind when form swaps) =====
        let observedIdEl = null;
        let idObserver = null;

        function observeIdInput(){
          const idEl = getIdInput();
          if (!idEl || idEl === observedIdEl) return;

          // cleanup old observer
          if (idObserver) { try { idObserver.disconnect(); } catch(e) {} }
          observedIdEl = idEl;

          // 1) Listen to events on id input (works even if only .value is set)
          idEl.addEventListener('change', scheduleVariantUpdate, true);
          idEl.addEventListener('input',  scheduleVariantUpdate, true);

          // 2) MutationObserver as bonus (if theme sets attribute/value)
          idObserver = new MutationObserver(() => scheduleVariantUpdate());
          try {
            idObserver.observe(idEl, { attributes: true, attributeFilter: ['value'] });
          } catch(e) {}
        }

        // Watch for form swaps / drawers / sticky ATC being injected
        const formSwapObserver = new MutationObserver(() => {
          observeIdInput();
        });
        try {
          formSwapObserver.observe(document.documentElement, { childList: true, subtree: true });
        } catch(e) {}

        // Global listeners (capture) — keep light, just schedule updates
        if (!window.__rtDiscountTableBound) {
          window.__rtDiscountTableBound = true;

          document.addEventListener('input', (e) => {
            if (e.target && e.target.matches('[name="quantity"], quantity-input input, input[type="number"]')) {
              scheduleQtyUpdate();
            }
          }, true);

          document.addEventListener('change', (e) => {
            // qty
            if (e.target && e.target.matches('[name="quantity"], quantity-input input, input[type="number"]')) {
              scheduleQtyUpdate();
              return;
            }
            // option interactions likely lead to id change
            if (
              e.target?.matches?.('input[type="radio"]') ||
              e.target?.matches?.('select') ||
              e.target?.matches?.('[name="id"]')
            ) {
              scheduleVariantUpdate();
            }
          }, true);

          document.addEventListener('click', (e) => {
            // common Horizon buttons/labels
            if (
              e.target?.closest?.('label.variant-option__button-label') ||
              e.target?.closest?.('[data-option-value]') ||
              e.target?.closest?.('variant-selects') ||
              e.target?.closest?.('variant-radios')
            ) {
              scheduleVariantUpdate();
            }
          }, true);
        }

        // init
        observeIdInput();
        render(true);
      })();
    </script>
  </div>
{%- endif -%}

