    }
  </style>

  <script>
  (function(){
    var rootId = {{ uid | json }};
    var root = document.getElementById(rootId);
    if(!root) return;
    if(root.__rtGasket2dInit) return;
    root.__rtGasket2dInit = true;

    var odRaw = {{ od_val | json }};
    var idRaw = {{ id_val | json }};
    var pcdRaw = {{ pcd_val | json }};
    var holeDiaRaw = {{ hole_dia_val | json }};
    var holeCountRaw = {{ hole_count_val | json }};
    var thkRaw = {{ thk_val | json }};

    function extractNumber(v){
      if (v == null) return null;
      if (typeof v === "object") {
        if (v.value != null) v = v.value;
        else if (v.amount != null) v = v.amount;
        else if (v.number != null) v = v.number;
        else return null;
      }
      if (typeof v === "number") return v;
      var s = String(v).trim().replace(",", ".");
      var m = s.match(/(\d+(\.\d+)?)/);
      return m ? Number(m[1]) : null;
    }

    function fmt(n){
      if (n == null) return "";
      var r = Math.round(n * 10) / 10;
      return String(r).replace(".", ",");
    }

    function qs(sel){ return root.querySelector(sel); }
    function setA(el,a,v){ if(el) el.setAttribute(a, String(v)); }

    var od = extractNumber(odRaw);
    var id = extractNumber(idRaw);
    var pcd = extractNumber(pcdRaw);
    var holeDia = extractNumber(holeDiaRaw);
    var holeCountNum = extractNumber(holeCountRaw);
    var holeCount = (holeCountNum != null) ? Math.max(1, Math.round(holeCountNum)) : null;
    var H = extractNumber(thkRaw);

    if(!od || !id || id <= 0 || od <= 0 || id >= od){
      root.style.display = "none";
      return;
    }

    var svg = qs("svg.rt-gasket2d__svg");
    if(!svg) return;

    var hasH = !!(H && H > 0);
    var hasHoles = !!(pcd && holeDia && holeCount && holeCount > 0);

    var cx = hasH ? 160 : 220;
    var cy = 170;

    var rOuter = (!hasH && !hasHoles) ? 105 : 90;
    var scale = rOuter / (od / 2);
    var rInner = (id / 2) * scale;

    var outer = qs(".outer-circle");
    var inner = qs(".inner-circle");
    var maskOuter = qs(".mask-outer");
    var maskInner = qs(".mask-inner");
    var pcdCircle = qs(".pcd-circle");

    [outer, inner, maskOuter, maskInner, pcdCircle].forEach(function(n){
      if(!n) return;
      setA(n, "cx", cx);
      setA(n, "cy", cy);
    });

    setA(outer, "r", rOuter);
    setA(inner, "r", rInner);
    setA(maskOuter, "r", rOuter);
    setA(maskInner, "r", rInner);

    var yDimOD = 28;
    var yDimID = 52;

    var xOL = cx - rOuter, xOR = cx + rOuter;
    var xIL = cx - rInner, xIR = cx + rInner;

    setA(qs(".od-ext-l"), "x1", xOL); setA(qs(".od-ext-l"), "x2", xOL);
    setA(qs(".od-ext-l"), "y1", yDimOD); setA(qs(".od-ext-l"), "y2", cy);

    setA(qs(".od-ext-r"), "x1", xOR); setA(qs(".od-ext-r"), "x2", xOR);
    setA(qs(".od-ext-r"), "y1", yDimOD); setA(qs(".od-ext-r"), "y2", cy);

    setA(qs(".od-line"), "x1", xOL); setA(qs(".od-line"), "x2", xOR);
    setA(qs(".od-line"), "y1", yDimOD); setA(qs(".od-line"), "y2", yDimOD);

    setA(qs(".od-text"), "x", cx); setA(qs(".od-text"), "y", yDimOD - 10);
    var odText = qs(".od-text"); if(odText) odText.textContent = fmt(od) + " mm";

    setA(qs(".id-ext-l"), "x1", xIL); setA(qs(".id-ext-l"), "x2", xIL);
    setA(qs(".id-ext-l"), "y1", yDimID); setA(qs(".id-ext-l"), "y2", cy);

    setA(qs(".id-ext-r"), "x1", xIR); setA(qs(".id-ext-r"), "x2", xIR);
    setA(qs(".id-ext-r"), "y1", yDimID); setA(qs(".id-ext-r"), "y2", cy);

    setA(qs(".id-line"), "x1", xIL); setA(qs(".id-line"), "x2", xIR);
    setA(qs(".id-line"), "y1", yDimID); setA(qs(".id-line"), "y2", yDimID);

    setA(qs(".id-text"), "x", cx); setA(qs(".id-text"), "y", yDimID - 10);
    var idText = qs(".id-text"); if(idText) idText.textContent = fmt(id) + " mm";

    var maskHolesGroup = qs(".mask-holes");
    var holeOutlinesGroup = qs(".hole-outlines");
    if(maskHolesGroup) maskHolesGroup.innerHTML = "";
    if(holeOutlinesGroup) holeOutlinesGroup.innerHTML = "";
    setA(pcdCircle, "r", 0);

    ["pcd-ext-l","pcd-ext-r","pcd-line","pcd-text","hole-ext-l","hole-ext-r","hole-line","hole-text"].forEach(function(cls){
      var n = qs("." + cls);
      if(n) n.style.display = "none";
    });

    var yDimPCD = null;

    if(hasHoles){
      ["pcd-ext-l","pcd-ext-r","pcd-line","pcd-text","hole-ext-l","hole-ext-r","hole-line","hole-text"].forEach(function(cls){
        var n = qs("." + cls);
        if(n) n.style.display = "";
      });

      var rPcd = (pcd / 2) * scale;
      var rHole = (holeDia / 2) * scale;
      setA(pcdCircle, "r", rPcd);

      var NS = "http://www.w3.org/2000/svg";
      var fragMask = document.createDocumentFragment();
      var fragOut = document.createDocumentFragment();

      var step = (Math.PI * 2) / holeCount;
      var rot = Math.PI / 2;

      for (var i = 0; i < holeCount; i++) {
        var a = rot + i * step;
        var x = cx + rPcd * Math.cos(a);
        var y = cy + rPcd * Math.sin(a);

        var cMask = document.createElementNS(NS, "circle");
        setA(cMask, "cx", x); setA(cMask, "cy", y); setA(cMask, "r", rHole);
        cMask.setAttribute("fill","black");
        fragMask.appendChild(cMask);

        var cOut = document.createElementNS(NS, "circle");
        setA(cOut, "cx", x); setA(cOut, "cy", y); setA(cOut, "r", rHole);
        fragOut.appendChild(cOut);
      }

      if(maskHolesGroup) maskHolesGroup.appendChild(fragMask);
      if(holeOutlinesGroup) holeOutlinesGroup.appendChild(fragOut);

      var yDimHole = cy + rOuter + 42;
      yDimPCD = yDimHole + 44;

      var holeCx = cx;
      var holeCy = cy + rPcd;
      var xHL = holeCx - rHole;
      var xHR = holeCx + rHole;

      setA(qs(".hole-ext-l"), "x1", xHL); setA(qs(".hole-ext-l"), "x2", xHL);
      setA(qs(".hole-ext-l"), "y1", holeCy); setA(qs(".hole-ext-l"), "y2", yDimHole);

      setA(qs(".hole-ext-r"), "x1", xHR); setA(qs(".hole-ext-r"), "x2", xHR);
      setA(qs(".hole-ext-r"), "y1", holeCy); setA(qs(".hole-ext-r"), "y2", yDimHole);

      setA(qs(".hole-line"), "x1", xHL); setA(qs(".hole-line"), "x2", xHR);
      setA(qs(".hole-line"), "y1", yDimHole); setA(qs(".hole-line"), "y2", yDimHole);

      setA(qs(".hole-text"), "x", holeCx); setA(qs(".hole-text"), "y", yDimHole + 16);
      var holeText = qs(".hole-text"); if(holeText) holeText.textContent = "Ø " + fmt(holeDia) + " mm";

      var xPL = cx - rPcd, xPR = cx + rPcd;

      setA(qs(".pcd-ext-l"), "x1", xPL); setA(qs(".pcd-ext-l"), "x2", xPL);
      setA(qs(".pcd-ext-l"), "y1", yDimPCD); setA(qs(".pcd-ext-l"), "y2", cy);

      setA(qs(".pcd-ext-r"), "x1", xPR); setA(qs(".pcd-ext-r"), "x2", xPR);
      setA(qs(".pcd-ext-r"), "y1", yDimPCD); setA(qs(".pcd-ext-r"), "y2", cy);

      setA(qs(".pcd-line"), "x1", xPL); setA(qs(".pcd-line"), "x2", xPR);
      setA(qs(".pcd-line"), "y1", yDimPCD); setA(qs(".pcd-line"), "y2", yDimPCD);

      setA(qs(".pcd-text"), "x", cx); setA(qs(".pcd-text"), "y", yDimPCD + 16);
      var pcdText = qs(".pcd-text"); if(pcdText) pcdText.textContent = "PCD " + fmt(pcd) + " mm";
    }

    var thkGroup = qs(".thk");
    if(thkGroup) thkGroup.style.display = "none";

    var thkRightEdge = null;
    var thkBottomEdge = null;

    if(H && H > 0 && thkGroup){
      thkGroup.style.display = "";

      var yTopOD = cy - rOuter;
      var yBotOD = cy + rOuter;

      var yTopID = cy - rInner;
      var yBotID = cy + rInner;

      var gap = 45;
      var stripW = 10;
      var x1 = cx + rOuter + gap;
      var x2 = x1 + stripW;

      setA(qs(".thk-left"), "x1", x1); setA(qs(".thk-left"), "x2", x1);
      setA(qs(".thk-left"), "y1", yTopOD); setA(qs(".thk-left"), "y2", yBotOD);

      setA(qs(".thk-right"), "x1", x2); setA(qs(".thk-right"), "x2", x2);
      setA(qs(".thk-right"), "y1", yTopOD); setA(qs(".thk-right"), "y2", yBotOD);

      setA(qs(".thk-top"), "x1", x1); setA(qs(".thk-top"), "x2", x2);
      setA(qs(".thk-top"), "y1", yTopOD); setA(qs(".thk-top"), "y2", yTopOD);

      setA(qs(".thk-bot"), "x1", x1); setA(qs(".thk-bot"), "x2", x2);
      setA(qs(".thk-bot"), "y1", yBotOD); setA(qs(".thk-bot"), "y2", yBotOD);

      setA(qs(".thk-id-top"), "x1", x1); setA(qs(".thk-id-top"), "x2", x2);
      setA(qs(".thk-id-top"), "y1", yTopID); setA(qs(".thk-id-top"), "y2", yTopID);

      setA(qs(".thk-id-bot"), "x1", x1); setA(qs(".thk-id-bot"), "x2", x2);
      setA(qs(".thk-id-bot"), "y1", yBotID); setA(qs(".thk-id-bot"), "y2", yBotID);

      var yDim = yTopOD - 22;
      setA(qs(".thk-dim"), "x1", x1); setA(qs(".thk-dim"), "x2", x2);
      setA(qs(".thk-dim"), "y1", yDim); setA(qs(".thk-dim"), "y2", yDim);

      setA(qs(".thk-text"), "x", (x1 + x2) / 2);
      setA(qs(".thk-text"), "y", yDim - 10);
      var thkText = qs(".thk-text"); if(thkText) thkText.textContent = fmt(H) + " mm";

      thkRightEdge = x2;
      thkBottomEdge = yBotOD;
    }

    var padTop = 22;
    var padBot = hasHoles ? 32 : 22;
    var padLR  = (H && H > 0) ? 30 : 22;

    var xMin = (cx - rOuter) - padLR;
    var xMax = (cx + rOuter) + padLR;

    if(thkRightEdge != null){
      xMax = Math.max(xMax, thkRightEdge + padLR);
    }

    var yMin = (yDimOD - padTop);

    var yMax;
    if(hasHoles){
      yMax = (yDimPCD != null ? (yDimPCD + 26) : (cy + rOuter + 98)) + padBot;
    } else {
      yMax = (cy + rOuter) + padBot;
    }

    if(thkBottomEdge != null){
      yMax = Math.max(yMax, thkBottomEdge + padBot);
    }

    var w = Math.max(10, xMax - xMin);
    var h = Math.max(10, yMax - yMin);

    svg.setAttribute("viewBox", [xMin, yMin, w, h].join(" "));
  })();
  </script>
{%- endif -%}

{%- comment -%}
  Sheet thickness table – NL only, Horizon aligned
  - Shows only if product.type contains "sheet" (case-insensitive)
  - Uses a variant option named exactly: "Dikte" OR "Thickness"
  - Desktop: full Horizon width
  - Mobile: horizontal scroll
  - Rows clickable to first matching variant for that thickness (optional but included)
{%- endcomment -%}

{%- assign include_only_available = true -%}

{%- assign product_type_norm = product.type | default: '' | strip | downcase -%}
{%- assign is_allowed_type = false -%}
{%- if product_type_norm contains 'sheet' -%}
  {%- assign is_allowed_type = true -%}
{%- endif -%}

{%- assign show_table = false -%}
{%- assign thickness_index = nil -%}

{%- if is_allowed_type -%}
  {%- comment -%}
    Trigger only if there is a variant option named exactly "Dikte" or "Thickness"
  {%- endcomment -%}
  {%- assign thickness_option_names = 'Dikte,Thickness' | split: ',' -%}

  {%- for candidate in thickness_option_names -%}
    {%- assign candidate = candidate | strip -%}
    {%- for opt_name in product.options -%}
      {%- if opt_name == candidate -%}
        {%- assign thickness_index = forloop.index0 -%}
        {%- break -%}
      {%- endif -%}
    {%- endfor -%}
    {%- if thickness_index != nil -%}{%- break -%}{%- endif -%}
  {%- endfor -%}

  {%- assign thickness_values = '' -%}
  {%- if thickness_index != nil -%}
    {%- for v in product.variants -%}
      {%- if include_only_available == false or v.available -%}
        {%- assign raw = v.options[thickness_index] | default: '' | strip -%}
        {%- assign cleaned = raw
          | downcase
          | replace: 'mm', ''
          | replace: ' ', ''
          | replace: ',', '.'
          | strip
        -%}
        {%- if cleaned != '' -%}
          {%- assign num = cleaned | plus: 0 -%}
          {%- if num != 0 or cleaned == '0' or cleaned == '0.0' -%}
            {%- assign thickness_values = thickness_values | append: cleaned | append: ',' -%}
          {%- endif -%}
        {%- endif -%}
      {%- endif -%}
    {%- endfor -%}
  {%- endif -%}

  {%- assign thicknesses_raw = thickness_values | split: ',' -%}

  {%- assign unique_list = '' -%}
  {%- for t in thicknesses_raw -%}
    {%- assign t = t | strip -%}
    {%- if t != '' -%}
      {%- assign token = '|' | append: t | append: '|' -%}
      {%- unless unique_list contains token -%}
        {%- assign unique_list = unique_list | append: token -%}
      {%- endunless -%}
    {%- endif -%}
  {%- endfor -%}
  {%- assign unique_items = unique_list | remove_first: '|' | split: '|' -%}

  {%- assign sortable = '' -%}
  {%- for t in unique_items -%}
    {%- assign t_num = t | plus: 0 -%}
    {%- assign key = t_num | times: 1000 | round -%}
    {%- assign key_str = key | append: '' -%}
    {%- assign pad = '00000000' -%}
    {%- assign key_padded = pad | append: key_str | slice: -8, 8 -%}
    {%- assign sortable = sortable | append: key_padded | append: '|' | append: t | append: ',' -%}
  {%- endfor -%}
  {%- assign sortable_arr = sortable | split: ',' | sort -%}

  {%- assign first_entry = sortable_arr[0] | default: '' | strip -%}
  {%- if first_entry != '' -%}
    {%- assign show_table = true -%}
  {%- endif -%}
{%- endif -%}

{%- if show_table -%}
  {%- assign uid = 'rt-sheet-table-' | append: product.id -%}

  {%- assign clean_title = product.title
    | replace: 'Gasket sheet', ''
    | replace: 'Gasket Sheet', ''
    | replace: 'Gasket sheets', ''
    | replace: 'Gasket Sheets', ''
    | strip
  -%}

  <section id="{{ uid }}" class="rt-sheet">
    <h3 class="rt-sheet__title">Afmetingen</h3>

    <div class="rt-sheet__scroll">
      <table class="rt-sheet__table">
        <colgroup>
          <col style="width: 46%;">
          <col style="width: 18%;">
          <col style="width: 18%;">
          <col style="width: 18%;">
        </colgroup>

        <thead>
          <tr>
            <th>Artikelnaam</th>
            <th>Dikte</th>
            <th>Max. lengte</th>
            <th>Max. breedte</th>
          </tr>
        </thead>

        <tbody>
          {%- for entry in sortable_arr -%}
            {%- assign entry = entry | strip -%}
            {%- if entry != '' -%}
              {%- assign parts = entry | split: '|' -%}
              {%- assign t = parts[1] | strip -%}

              {%- if t != blank -%}
                {%- assign row_href = '' -%}
                {%- if thickness_index != nil -%}
                  {%- for v in product.variants -%}
                    {%- if include_only_available == false or v.available -%}
                      {%- assign raw2 = v.options[thickness_index] | default: '' | strip -%}
                      {%- assign cleaned2 = raw2
                        | downcase
                        | replace: 'mm', ''
                        | replace: ' ', ''
                        | replace: ',', '.'
                        | strip
                      -%}
                      {%- if cleaned2 == t -%}
                        {%- assign row_href = product.url | append: '?variant=' | append: v.id -%}
                        {%- break -%}
                      {%- endif -%}
                    {%- endif -%}
                  {%- endfor -%}
                {%- endif -%}

                <tr class="rt-sheet__row"{% if row_href != '' %} data-href="{{ row_href }}"{% endif %}>
                  <td>{{ clean_title }} {{ t }} mm</td>
                  <td>{{ t }} mm</td>
                  <td>2000 mm</td>
                  <td>1000 mm</td>
                </tr>
              {%- endif -%}
            {%- endif -%}
          {%- endfor -%}

          <tr class="rt-sheet__footer">
            <td colspan="4">
              {{ clean_title }} zijn op maat leverbaar. Grotere afmetingen en speciale vormen zijn mogelijk op aanvraag.
            </td>
          </tr>
        </tbody>
      </table>
    </div>
  </section>

  <style>
    /* Horizon aligned (theme controls overall width) */
    #{{ uid }}.rt-sheet{
      width: 100%;
      margin: 24px 0;
      padding: 24px 0;
    }

    #{{ uid }} .rt-sheet__title{
      margin: 0 0 24px;
      font-size: 32px;
      line-height: 1.1;
      font-weight: 750;
      color: #003878;
    }

    #{{ uid }} .rt-sheet__scroll{
      width: 100%;
      overflow-x: auto;
      overflow-y: hidden;
      -webkit-overflow-scrolling: touch;
    }

    #{{ uid }} .rt-sheet__table{
      width: 100%;
      border-collapse: collapse;
      font-size: 15px;
      background: #fff;
      table-layout: fixed;
    }

    #{{ uid }} .rt-sheet__table th,
    #{{ uid }} .rt-sheet__table td{
      border: 1px solid #A0B2C9;
      padding: 12px 12px;
      text-align: center;
      white-space: nowrap;
      vertical-align: middle;
    }

    #{{ uid }} .rt-sheet__table td:first-child,
    #{{ uid }} .rt-sheet__table th:first-child{
      text-align: left;
      white-space: normal;
      word-break: break-word;
    }

    #{{ uid }} .rt-sheet__table td:first-child{
      font-weight: 700;
    }

    #{{ uid }} .rt-sheet__table thead th{
      background: #003878;
      color: #fff;
      font-weight: 800;
    }

    #{{ uid }} .rt-sheet__table tbody tr:nth-child(even){
      background: #EDF0F2;
    }

    #{{ uid }} .rt-sheet__row{
      cursor: default;
    }
    #{{ uid }} .rt-sheet__row[data-href]{
      cursor: pointer;
    }
    #{{ uid }} .rt-sheet__row[data-href]:hover td{
      color: #FF7300;
    }

    #{{ uid }} .rt-sheet__footer td{
      text-align: left;
      font-weight: 400;
      white-space: normal;
      color: inherit;
    }

    @media (max-width: 749px){
      #{{ uid }} .rt-sheet__table{
        width: auto;
        min-width: 720px;
      }
    }
  </style>

  <script>
  (function(){
    var root = document.getElementById({{ uid | json }});
    if(!root) return;
    if(root.__rtSheetInit) return;
    root.__rtSheetInit = true;

    root.addEventListener("click", function(e){
      var tr = e.target.closest("tr[data-href]");
      if(!tr) return;
      var href = tr.getAttribute("data-href");
      if(href) window.location.href = href;
    });
  })();
  </script>
{%- endif -%}

{%- comment -%}
  UPDATE:
  - Added 24px radius to the image box
  - Set background to #EDF0F2
  - Text set to black, Title set to blue
{%- endcomment -%}

{%- assign v = product.selected_or_first_available_variant -%}

{%- assign od_val = v.metafields.custom.outer_diameter.value | default: product.metafields.custom.outer_diameter.value -%}
{%- assign id_val = v.metafields.custom.inner_diameter.value | default: product.metafields.custom.inner_diameter.value -%}

{%- if od_val != blank and id_val != blank -%}
  {%- assign uid = 'rt-gasket2d-' | append: product.id -%}

  {%- assign pcd_val = v.metafields.custom.pitch_circle.value | default: product.metafields.custom.pitch_circle.value -%}
  {%- assign hole_dia_val = v.metafields.custom.bolt_holes_diameter.value | default: product.metafields.custom.bolt_holes_diameter.value -%}
  {%- assign hole_count_val = v.metafields.custom.bolt_holes_count.value | default: product.metafields.custom.bolt_holes_count.value -%}
  {%- assign thk_val = v.metafields.custom.thickness.value | default: product.metafields.custom.thickness.value -%}

  <section id="{{ uid }}" class="rt-gasket2d">
    <div class="rt-gasket2d__inner page-width">
      <div class="rt-gasket2d__wrap">
        <!-- LEFT: TABLE -->
        <div class="rt-gasket2d__left">
          <h3 class="rt-gasket2d__title">Afmetingen</h3>

          <table class="rt-gasket2d__table" aria-label="Dimensions">
            <thead>
              <tr>
                <th scope="col">Kenmerk</th>
                <th scope="col">Waarde</th>
              </tr>
            </thead>
            <tbody>
              {%- if od_val != blank -%}
                <tr>
                  <td>Buitendiameter (OD)</td>
                  <td>{{ od_val }} mm</td>
                </tr>
              {%- endif -%}

              {%- if id_val != blank -%}
                <tr>
                  <td>Binnendiameter (ID)</td>
                  <td>{{ id_val }} mm</td>
                </tr>
              {%- endif -%}

              {%- if thk_val != blank -%}
                <tr>
                  <td>Dikte (H)</td>
                  <td>{{ thk_val }} mm</td>
                </tr>
              {%- endif -%}

              {%- if pcd_val != blank -%}
                <tr>
                  <td>Steekcirkel (PCD)</td>
                  <td>{{ pcd_val }} mm</td>
                </tr>
              {%- endif -%}

              {%- if hole_dia_val != blank -%}
                <tr>
                  <td>Boutgat Ø</td>
                  <td>Ø {{ hole_dia_val }} mm</td>
                </tr>
              {%- endif -%}

              {%- if hole_count_val != blank -%}
                <tr>
                  <td>Boutgaten</td>
                  <td>{{ hole_count_val }}</td>
                </tr>
              {%- endif -%}
            </tbody>
          </table>
        </div>

        <!-- RIGHT: RENDER -->
        <div class="rt-gasket2d__right">
          <div class="rt-gasket2d__box" aria-label="2D drawing box">
            <svg class="rt-gasket2d__svg"
                 viewBox="0 0 440 520"
                 preserveAspectRatio="xMidYMid meet"
                 role="img"
                 aria-label="2D gasket with dimensions">

              <defs>
                <marker id="{{ uid }}-arrow" viewBox="0 0 10 10" refX="5" refY="5"
                        markerWidth="5" markerHeight="5" orient="auto-start-reverse">
                  <path d="M 0 0 L 10 5 L 0 10 z" fill="currentColor"></path>
                </marker>

                <pattern id="{{ uid }}-hatch" patternUnits="userSpaceOnUse" width="7" height="7" patternTransform="rotate(25)">
                  <line class="hatch-line" x1="0" y1="0" x2="0" y2="7"></line>
                </pattern>

                <mask id="{{ uid }}-ringmask">
                  <rect width="100%" height="100%" fill="black"></rect>
                  <circle class="mask-outer" cx="160" cy="170" r="0" fill="white"></circle>
                  <circle class="mask-inner" cx="160" cy="170" r="0" fill="black"></circle>
                  <g class="mask-holes"></g>
                </mask>
              </defs>

              <g class="gasket-shape" aria-hidden="true">
                <circle class="outer-circle" cx="160" cy="170" r="0"></circle>
                <circle class="inner-circle" cx="160" cy="170" r="0"></circle>

                <rect class="ring-fill"
                      x="0" y="0" width="440" height="520"
                      mask="url(#{{ uid }}-ringmask)"></rect>

                <rect class="ring-hatch"
                      x="0" y="0" width="440" height="520"
                      fill="url(#{{ uid }}-hatch)"
                      mask="url(#{{ uid }}-ringmask)"></rect>

                <g class="hole-outlines"></g>
                <circle class="pcd-circle" cx="160" cy="170" r="0"></circle>
              </g>

              <g class="gasket-dims" aria-hidden="true">
                <line class="dim-ext od-ext-l"></line>
                <line class="dim-ext od-ext-r"></line>
                <line class="dim-line od-line"
                      marker-start="url(#{{ uid }}-arrow)"
                      marker-end="url(#{{ uid }}-arrow)"></line>
                <text class="dim-text od-text" text-anchor="middle"></text>

                <line class="dim-ext id-ext-l"></line>
                <line class="dim-ext id-ext-r"></line>
                <line class="dim-line id-line"
                      marker-start="url(#{{ uid }}-arrow)"
                      marker-end="url(#{{ uid }}-arrow)"></line>
                <text class="dim-text id-text" text-anchor="middle"></text>

                <line class="dim-ext hole-ext-l"></line>
                <line class="dim-ext hole-ext-r"></line>
                <line class="dim-line hole-line"
                      marker-start="url(#{{ uid }}-arrow)"
                      marker-end="url(#{{ uid }}-arrow)"></line>
                <text class="dim-text hole-text" text-anchor="middle"></text>

                <line class="dim-ext pcd-ext-l"></line>
                <line class="dim-ext pcd-ext-r"></line>
                <line class="dim-line pcd-line"
                      marker-start="url(#{{ uid }}-arrow)"
                      marker-end="url(#{{ uid }}-arrow)"></line>
                <text class="dim-text pcd-text" text-anchor="middle"></text>

                <g class="thk" style="display:none">
                  <line class="thk-vert thk-left"></line>
                  <line class="thk-vert thk-right"></line>
                  <line class="thk-h thk-top"></line>
                  <line class="thk-h thk-bot"></line>
                  <line class="thk-id-top"></line>
                  <line class="thk-id-bot"></line>

                  <line class="dim-line thk-dim"
                        marker-start="url(#{{ uid }}-arrow)"
                        marker-end="url(#{{ uid }}-arrow)"></line>
                  <text class="dim-text thk-text" text-anchor="middle"></text>
                </g>
              </g>
            </svg>
          </div>
        </div>
      </div>
    </div>
  </section>

