  <script>
  (function(){
    var rootId = {{ uid | json }};
    var root = document.getElementById(rootId);
    if(!root) return;
    if(root.__rtGasket2dInit) return;
    root.__rtGasket2dInit = true;

    var odRaw = {{ od_val | json }};
    var idRaw = {{ id_val | json }};
    var pcdRaw = {{ pcd_val | json }};
    var holeDiaRaw = {{ hole_dia_val | json }};
    var holeCountRaw = {{ hole_count_val | json }};
    var thkRaw = {{ thk_val | json }};

    function extractNumber(v){
      if (v == null) return null;
      if (typeof v === "object") {
        if (v.value != null) v = v.value;
        else if (v.amount != null) v = v.amount;
        else if (v.number != null) v = v.number;
        else return null;
      }
      if (typeof v === "number") return v;
      var s = String(v).trim().replace(",", ".");
      var m = s.match(/(\d+(\.\d+)?)/);
      return m ? Number(m[1]) : null;
    }

    function fmt(n){
      if (n == null) return "";
      var r = Math.round(n * 10) / 10;
      return String(r).replace(".", ",");
    }

    function qs(sel){ return root.querySelector(sel); }
    function setA(el,a,v){ if(el) el.setAttribute(a, String(v)); }

    var od = extractNumber(odRaw);
    var id = extractNumber(idRaw);
    var pcd = extractNumber(pcdRaw);
    var holeDia = extractNumber(holeDiaRaw);
    var holeCountNum = extractNumber(holeCountRaw);
    var holeCount = (holeCountNum != null) ? Math.max(1, Math.round(holeCountNum)) : null;
    var H = extractNumber(thkRaw);

    if(!od || !id || id <= 0 || od <= 0 || id >= od){
      root.style.display = "none";
      return;
    }

    var svg = qs("svg.rt-gasket2d__svg");
    if(!svg) return;

    var hasH = !!(H && H > 0);
    var hasHoles = !!(pcd && holeDia && holeCount && holeCount > 0);

    var cx = hasH ? 160 : 220;
    var cy = 170;

    var rOuter = (!hasH && !hasHoles) ? 105 : 90;
    var scale = rOuter / (od / 2);
    var rInner = (id / 2) * scale;

    var outer = qs(".outer-circle");
    var inner = qs(".inner-circle");
    var maskOuter = qs(".mask-outer");
    var maskInner = qs(".mask-inner");
    var pcdCircle = qs(".pcd-circle");

    [outer, inner, maskOuter, maskInner, pcdCircle].forEach(function(n){
      if(!n) return;
      setA(n, "cx", cx);
      setA(n, "cy", cy);
    });

    setA(outer, "r", rOuter);
    setA(inner, "r", rInner);
    setA(maskOuter, "r", rOuter);
    setA(maskInner, "r", rInner);

    var yDimOD = 28;
    var yDimID = 52;

    var xOL = cx - rOuter, xOR = cx + rOuter;
    var xIL = cx - rInner, xIR = cx + rInner;

    setA(qs(".od-ext-l"), "x1", xOL); setA(qs(".od-ext-l"), "x2", xOL);
    setA(qs(".od-ext-l"), "y1", yDimOD); setA(qs(".od-ext-l"), "y2", cy);

    setA(qs(".od-ext-r"), "x1", xOR); setA(qs(".od-ext-r"), "x2", xOR);
    setA(qs(".od-ext-r"), "y1", yDimOD); setA(qs(".od-ext-r"), "y2", cy);

    setA(qs(".od-line"), "x1", xOL); setA(qs(".od-line"), "x2", xOR);
    setA(qs(".od-line"), "y1", yDimOD); setA(qs(".od-line"), "y2", yDimOD);

    setA(qs(".od-text"), "x", cx); setA(qs(".od-text"), "y", yDimOD - 10);
    var odText = qs(".od-text"); if(odText) odText.textContent = fmt(od) + " mm";

    setA(qs(".id-ext-l"), "x1", xIL); setA(qs(".id-ext-l"), "x2", xIL);
    setA(qs(".id-ext-l"), "y1", yDimID); setA(qs(".id-ext-l"), "y2", cy);

    setA(qs(".id-ext-r"), "x1", xIR); setA(qs(".id-ext-r"), "x2", xIR);
    setA(qs(".id-ext-r"), "y1", yDimID); setA(qs(".id-ext-r"), "y2", cy);

    setA(qs(".id-line"), "x1", xIL); setA(qs(".id-line"), "x2", xIR);
    setA(qs(".id-line"), "y1", yDimID); setA(qs(".id-line"), "y2", yDimID);

    setA(qs(".id-text"), "x", cx); setA(qs(".id-text"), "y", yDimID - 10);
    var idText = qs(".id-text"); if(idText) idText.textContent = fmt(id) + " mm";

    var maskHolesGroup = qs(".mask-holes");
    var holeOutlinesGroup = qs(".hole-outlines");
    if(maskHolesGroup) maskHolesGroup.innerHTML = "";
    if(holeOutlinesGroup) holeOutlinesGroup.innerHTML = "";
    setA(pcdCircle, "r", 0);

    ["pcd-ext-l","pcd-ext-r","pcd-line","pcd-text","hole-ext-l","hole-ext-r","hole-line","hole-text"].forEach(function(cls){
      var n = qs("." + cls);
      if(n) n.style.display = "none";
    });

    var yDimPCD = null;

    if(hasHoles){
      ["pcd-ext-l","pcd-ext-r","pcd-line","pcd-text","hole-ext-l","hole-ext-r","hole-line","hole-text"].forEach(function(cls){
        var n = qs("." + cls);
        if(n) n.style.display = "";
      });

      var rPcd = (pcd / 2) * scale;
      var rHole = (holeDia / 2) * scale;
      setA(pcdCircle, "r", rPcd);

      var NS = "http://www.w3.org/2000/svg";
      var fragMask = document.createDocumentFragment();
      var fragOut = document.createDocumentFragment();

      var step = (Math.PI * 2) / holeCount;
      var rot = Math.PI / 2;

      for (var i = 0; i < holeCount; i++) {
        var a = rot + i * step;
        var x = cx + rPcd * Math.cos(a);
        var y = cy + rPcd * Math.sin(a);

        var cMask = document.createElementNS(NS, "circle");
        setA(cMask, "cx", x); setA(cMask, "cy", y); setA(cMask, "r", rHole);
        cMask.setAttribute("fill","black");
        fragMask.appendChild(cMask);

        var cOut = document.createElementNS(NS, "circle");
        setA(cOut, "cx", x); setA(cOut, "cy", y); setA(cOut, "r", rHole);
        fragOut.appendChild(cOut);
      }

      if(maskHolesGroup) maskHolesGroup.appendChild(fragMask);
      if(holeOutlinesGroup) holeOutlinesGroup.appendChild(fragOut);

      var yDimHole = cy + rOuter + 42;
      yDimPCD = yDimHole + 44;

      var holeCx = cx;
      var holeCy = cy + rPcd;
      var xHL = holeCx - rHole;
      var xHR = holeCx + rHole;

      setA(qs(".hole-ext-l"), "x1", xHL); setA(qs(".hole-ext-l"), "x2", xHL);
      setA(qs(".hole-ext-l"), "y1", holeCy); setA(qs(".hole-ext-l"), "y2", yDimHole);

      setA(qs(".hole-ext-r"), "x1", xHR); setA(qs(".hole-ext-r"), "x2", xHR);
      setA(qs(".hole-ext-r"), "y1", holeCy); setA(qs(".hole-ext-r"), "y2", yDimHole);

      setA(qs(".hole-line"), "x1", xHL); setA(qs(".hole-line"), "x2", xHR);
      setA(qs(".hole-line"), "y1", yDimHole); setA(qs(".hole-line"), "y2", yDimHole);

      setA(qs(".hole-text"), "x", holeCx); setA(qs(".hole-text"), "y", yDimHole + 16);
      var holeText = qs(".hole-text"); if(holeText) holeText.textContent = "Ø " + fmt(holeDia) + " mm";

      var xPL = cx - rPcd, xPR = cx + rPcd;

      setA(qs(".pcd-ext-l"), "x1", xPL); setA(qs(".pcd-ext-l"), "x2", xPL);
      setA(qs(".pcd-ext-l"), "y1", yDimPCD); setA(qs(".pcd-ext-l"), "y2", cy);

      setA(qs(".pcd-ext-r"), "x1", xPR); setA(qs(".pcd-ext-r"), "x2", xPR);
      setA(qs(".pcd-ext-r"), "y1", yDimPCD); setA(qs(".pcd-ext-r"), "y2", cy);

      setA(qs(".pcd-line"), "x1", xPL); setA(qs(".pcd-line"), "x2", xPR);
      setA(qs(".pcd-line"), "y1", yDimPCD); setA(qs(".pcd-line"), "y2", yDimPCD);

      setA(qs(".pcd-text"), "x", cx); setA(qs(".pcd-text"), "y", yDimPCD + 16);
      var pcdText = qs(".pcd-text"); if(pcdText) pcdText.textContent = "PCD " + fmt(pcd) + " mm";
    }

    var thkGroup = qs(".thk");
    if(thkGroup) thkGroup.style.display = "none";

    var thkRightEdge = null;
    var thkBottomEdge = null;

    if(H && H > 0 && thkGroup){
      thkGroup.style.display = "";

      var yTopOD = cy - rOuter;
      var yBotOD = cy + rOuter;

      var yTopID = cy - rInner;
      var yBotID = cy + rInner;

      var gap = 45;
      var stripW = 10;
      var x1 = cx + rOuter + gap;
      var x2 = x1 + stripW;

      setA(qs(".thk-left"), "x1", x1); setA(qs(".thk-left"), "x2", x1);
      setA(qs(".thk-left"), "y1", yTopOD); setA(qs(".thk-left"), "y2", yBotOD);

      setA(qs(".thk-right"), "x1", x2); setA(qs(".thk-right"), "x2", x2);
      setA(qs(".thk-right"), "y1", yTopOD); setA(qs(".thk-right"), "y2", yBotOD);

      setA(qs(".thk-top"), "x1", x1); setA(qs(".thk-top"), "x2", x2);
      setA(qs(".thk-top"), "y1", yTopOD); setA(qs(".thk-top"), "y2", yTopOD);

      setA(qs(".thk-bot"), "x1", x1); setA(qs(".thk-bot"), "x2", x2);
      setA(qs(".thk-bot"), "y1", yBotOD); setA(qs(".thk-bot"), "y2", yBotOD);

      setA(qs(".thk-id-top"), "x1", x1); setA(qs(".thk-id-top"), "x2", x2);
      setA(qs(".thk-id-top"), "y1", yTopID); setA(qs(".thk-id-top"), "y2", yTopID);

      setA(qs(".thk-id-bot"), "x1", x1); setA(qs(".thk-id-bot"), "x2", x2);
      setA(qs(".thk-id-bot"), "y1", yBotID); setA(qs(".thk-id-bot"), "y2", yBotID);

      var yDim = yTopOD - 22;
      setA(qs(".thk-dim"), "x1", x1); setA(qs(".thk-dim"), "x2", x2);
      setA(qs(".thk-dim"), "y1", yDim); setA(qs(".thk-dim"), "y2", yDim);

      setA(qs(".thk-text"), "x", (x1 + x2) / 2);
      setA(qs(".thk-text"), "y", yDim - 10);
      var thkText = qs(".thk-text"); if(thkText) thkText.textContent = fmt(H) + " mm";

      thkRightEdge = x2;
      thkBottomEdge = yBotOD;
    }

    var padTop = 22;
    var padBot = hasHoles ? 32 : 22;
    var padLR  = (H && H > 0) ? 30 : 22;

    var xMin = (cx - rOuter) - padLR;
    var xMax = (cx + rOuter) + padLR;

    if(thkRightEdge != null){
      xMax = Math.max(xMax, thkRightEdge + padLR);
    }

    var yMin = (yDimOD - padTop);

    var yMax;
    if(hasHoles){
      yMax = (yDimPCD != null ? (yDimPCD + 26) : (cy + rOuter + 98)) + padBot;
    } else {
      yMax = (cy + rOuter) + padBot;
    }

    if(thkBottomEdge != null){
      yMax = Math.max(yMax, thkBottomEdge + padBot);
    }

    var w = Math.max(10, xMax - xMin);
    var h = Math.max(10, yMax - yMin);

    svg.setAttribute("viewBox", [xMin, yMin, w, h].join(" "));
  })();
  </script>
{%- endif -%}

{%- comment -%}
  DN table – Horizon aligned
  - Desktop: full Horizon width (theme controls)
  - Mobile: horizontal scroll
  - Clickable rows (test URL)
{%- endcomment -%}

{%- assign uid = 'rt-dn-table-' | append: product.id -%}
{%- assign row_url = '/products/test-kopie' -%}
{%- assign dns = '10,15,20,25,32,40,50,65,80,100' | split: ',' -%}

<section id="{{ uid }}" class="rt-dn">
  <h3 class="rt-dn__title">DN Dimensions</h3>

  <div class="rt-dn__scroll">
    <table class="rt-dn__table">
      <thead>
        <tr>
          <th>DN</th>
          <th>OD</th>
          <th>ID</th>
          <th>PCD</th>
          <th>Gaten</th>
          <th>Boutgat Ø</th>
        </tr>
      </thead>

      <tbody>
        {%- for dn in dns -%}
          <tr class="rt-dn__row" data-href="{{ row_url }}">
            <td><strong>DN{{ dn | strip }}</strong></td>
            <td>— mm</td>
            <td>— mm</td>
            <td>— mm</td>
            <td>—</td>
            <td>Ø — mm</td>
          </tr>
        {%- endfor -%}
      </tbody>
    </table>
  </div>
</section>

<style>
  /* Let Horizon control the width */
  #{{ uid }}.rt-dn{
    width: 100%;
    margin: 24px 0;
    padding: 24px 0; /* ✅ 24px top/bottom padding */
  }

  #{{ uid }} .rt-dn__title{
    margin: 0 0 24px;          /* ✅ 24px spacing under title */
    font-size: 32px;           /* ✅ 32px title */
    line-height: 1.1;
    font-weight: 750;
    color: #003878;
  }

  /* Scroll wrapper */
  #{{ uid }} .rt-dn__scroll{
    width: 100%;
    overflow-x: auto;
    overflow-y: hidden;
    -webkit-overflow-scrolling: touch;
  }

  /* Table */
  #{{ uid }} .rt-dn__table{
    width: 100%;
    border-collapse: collapse;
    font-size: 15px;
    background: #fff;
  }

  /* Lines */
  #{{ uid }} .rt-dn__table th,
  #{{ uid }} .rt-dn__table td{
    border: 1px solid #A0B2C9;
    padding: 12px 12px;
    text-align: center;
    white-space: nowrap;
  }

  /* Header */
  #{{ uid }} .rt-dn__table thead th{
    background: #003878;
    color: #fff;
    font-weight: 800;
  }

  /* Zebra */
  #{{ uid }} .rt-dn__table tbody tr:nth-child(even){
    background: #EDF0F2;
  }

  /* Hover */
  #{{ uid }} .rt-dn__row{
    cursor: pointer;
  }
  #{{ uid }} .rt-dn__row:hover td{
    color: #FF7300;
  }

  /* Mobile only: allow horizontal scroll */
  @media (max-width: 749px){
    #{{ uid }} .rt-dn__table{
      width: auto;
      min-width: 700px;
    }
  }
</style>

<script>
(function(){
  var root = document.getElementById({{ uid | json }});
  if(!root) return;
  if(root.__rtDnInit) return;
  root.__rtDnInit = true;

  root.addEventListener("click", function(e){
    var tr = e.target.closest("tr[data-href]");
    if(!tr) return;
    var href = tr.getAttribute("data-href");
    if(href) window.location.href = href;
  });
})();
</script>

{%- liquid
  assign p = product | default: closest.product

  assign col_ref = p.metafields.custom.collectie.value

  comment
    OPTION NAMING:
    - Change these to match your store exactly (case sensitive).
  endcomment
  assign opt_color_name = 'Color'
  assign opt_spec_name  = 'Specification'

  assign color_list = ''
  assign spec_first = ''

  for opt in p.options_with_values
    if opt.name == opt_color_name
      assign color_list = opt.values | join: ', '
    endif
    if opt.name == opt_spec_name
      assign spec_first = opt.values.first
    endif
  endfor

  assign has_rows = false
  if col_ref != blank or color_list != blank or spec_first != blank
    assign has_rows = true
  endif
-%}

{%- if has_rows -%}
  <section class="rt-specs" aria-label="Specificaties">
    <div class="page-width">
      <div class="rt-specs__tablewrap">
        <table class="rt-specs__table" role="table">
          <tbody>

            {%- if col_ref != blank -%}
              <tr>
                <th scope="row">Categorie</th>
                <td>
                  <a class="rt-specs__link" href="{{ col_ref.url }}">{{ col_ref.title }}</a>
                </td>
              </tr>
            {%- endif -%}

            {%- if color_list != blank -%}
              <tr>
                <th scope="row">Kleur</th>
                <td>{{ color_list }}</td>
              </tr>
            {%- endif -%}

            {%- if spec_first != blank -%}
              <tr>
                <th scope="row">Specificatie</th>
                <td>{{ spec_first }}</td>
              </tr>
            {%- endif -%}

          </tbody>
        </table>
      </div>
    </div>
  </section>

  <style>
    .rt-specs{ margin: 22px 0; }
    .rt-specs__table{
      width: 100%;
      border-collapse: collapse;
      table-layout: fixed;
      background: #fff;
      font-size: 14px;
      line-height: 1.35;
    }
    .rt-specs__table th,
    .rt-specs__table td{
      width: 50%;
      padding: 12px 14px;
      vertical-align: middle;
      text-align: left;
      color: inherit;
      word-break: break-word;
    }
    .rt-specs__table th{ font-weight: 600; }
    .rt-specs__table tbody tr:nth-child(odd){ background: #EDF0F2; }
    .rt-specs__link{
      color: inherit;
      text-decoration: underline;
      text-underline-offset: 2px;
    }
    .rt-specs__link:hover{ color:#003878; }
  </style>
{%- endif -%}

{%- comment -%}
  RECHTHOEK / STRIP 2D — Horizon-friendly (mobiel gefixt)

  Fixes:
  - Mobiel: kleinere gap + geen grote witruimte tussen tabel en SVG
  - Breedte: volgt Horizon container (geen overflow / niet breder dan page width)
  - SVG nudge teruggedraaid: weer netjes binnen Horizon pagina breedte
  - Links blok verticaal gecentreerd op desktop, normaal op mobiel
  - Category metafields op PRODUCT niveau (MetaobjectListDrop)
  - "Kleur" i.p.v. "Kleur / patroon" (patroon weggehaald)
{%- endcomment -%}

{%- assign v = product.selected_or_first_available_variant -%}

{%- assign len_val = v.metafields.custom.length.value | default: product.metafields.custom.length.value -%}
{%- assign wid_val = v.metafields.custom.width.value  | default: product.metafields.custom.width.value  -%}
{%- assign thk_val = v.metafields.custom.thickness.value | default: product.metafields.custom.thickness.value -%}

{%- assign shape_list = product.metafields.shopify.shape.value -%}
{%- assign material_list = product.metafields.shopify.material.value -%}
{%- assign color_list = product.metafields.shopify['color-pattern'].value -%}

{%- capture shape_text -%}
  {%- if shape_list != blank -%}
    {%- for it in shape_list -%}
      {%- assign label = it.system.title | default: it.title | default: it.name | default: it.system.handle | default: it.handle -%}
      {%- if label != blank -%}{{- label -}}{%- unless forloop.last -%}, {%- endunless -%}{%- endif -%}
    {%- endfor -%}
  {%- endif -%}
{%- endcapture -%}
{%- assign shape_text = shape_text | strip -%}

{%- capture material_text -%}
  {%- if material_list != blank -%}
    {%- for it in material_list -%}
      {%- assign label = it.system.title | default: it.title | default: it.name | default: it.system.handle | default: it.handle -%}
      {%- if label != blank -%}{{- label -}}{%- unless forloop.last -%}, {%- endunless -%}{%- endif -%}
    {%- endfor -%}
  {%- endif -%}
{%- endcapture -%}
{%- assign material_text = material_text | strip -%}

{%- capture color_text -%}
  {%- if color_list != blank -%}
    {%- for it in color_list -%}
      {%- assign raw = it.system.title | default: it.title | default: it.name | default: it.system.handle | default: it.handle -%}
      {%- if raw != blank -%}
        {%- assign part = raw | split: ' / ' | first -%}
        {%- assign part = part | split: ' - ' | first -%}
        {%- assign part = part | split: ' | ' | first -%}
        {%- assign part = part | split: ',' | first -%}
        {{- part | strip -}}{%- unless forloop.last -%}, {%- endunless -%}
      {%- endif -%}
    {%- endfor -%}
  {%- endif -%}
{%- endcapture -%}
{%- assign color_text = color_text | strip -%}

{%- if len_val != blank and wid_val != blank -%}
  {%- assign uid = 'rt-rect2d-' | append: product.id -%}

  <section id="{{ uid }}" class="rt-rect2d">
    <div class="rt-rect2d__wrap">
      <!-- LINKS: TABEL -->
      <div class="rt-rect2d__left">
        <div class="rt-rect2d__left-inner">
          <h3 class="rt-rect2d__title">Afmetingen</h3>

          <table class="rt-rect2d__table" aria-label="Afmetingen">
            <thead>
              <tr>
                <th scope="col">Kenmerk</th>
                <th scope="col">Waarde</th>
              </tr>
            </thead>
            <tbody>
              <tr><td>Lengte</td><td>{{ len_val }} mm</td></tr>
              <tr><td>Breedte</td><td>{{ wid_val }} mm</td></tr>

              {%- if thk_val != blank -%}
                <tr><td>Dikte</td><td>{{ thk_val }} mm</td></tr>
              {%- endif -%}

              {%- if shape_text != blank -%}
                <tr><td>Vorm</td><td>{{ shape_text }}</td></tr>
              {%- endif -%}
              {%- if material_text != blank -%}
                <tr><td>Materiaal</td><td>{{ material_text }}</td></tr>
              {%- endif -%}
              {%- if color_text != blank -%}
                <tr><td>Kleur</td><td>{{ color_text }}</td></tr>
              {%- endif -%}
            </tbody>
          </table>
        </div>
      </div>

      <!-- RECHTS: SVG -->
      <div class="rt-rect2d__right">
        <div class="rt-rect2d__box" aria-label="2D tekening box">
          <svg class="rt-rect2d__svg"
               viewBox="0 0 720 420"
               preserveAspectRatio="xMidYMid meet"
               role="img"
               aria-label="2D rechthoek met afmetingen">

            <defs>
              <marker id="{{ uid }}-arrow" viewBox="0 0 10 10" refX="5" refY="5"
                      markerWidth="5" markerHeight="5" orient="auto-start-reverse">
                <path d="M 0 0 L 10 5 L 0 10 z" fill="currentColor"></path>
              </marker>

              <pattern id="{{ uid }}-hatch" patternUnits="userSpaceOnUse" width="7" height="7" patternTransform="rotate(25)">
                <line class="hatch-line" x1="0" y1="0" x2="0" y2="7"></line>
              </pattern>
            </defs>

            <g class="shape" aria-hidden="true">
              <rect class="rect-fill" x="0" y="0" width="0" height="0"></rect>
              <rect class="rect-hatch" x="0" y="0" width="0" height="0" fill="url(#{{ uid }}-hatch)"></rect>
              <rect class="rect-stroke" x="0" y="0" width="0" height="0"></rect>
            </g>

            <g class="dims" aria-hidden="true">
              <!-- BOVEN: Lengte -->
              <line class="dim-ext len-ext-l"></line>
              <line class="dim-ext len-ext-r"></line>
              <line class="dim-line len-line" marker-start="url(#{{ uid }}-arrow)" marker-end="url(#{{ uid }}-arrow)"></line>
              <text class="dim-text len-text" text-anchor="middle"></text>

              <!-- LINKS: Breedte -->
              <line class="dim-ext wid-ext-t"></line>
              <line class="dim-ext wid-ext-b"></line>
              <line class="dim-line wid-line" marker-start="url(#{{ uid }}-arrow)" marker-end="url(#{{ uid }}-arrow)"></line>
              <text class="dim-text wid-text" text-anchor="end"></text>
            </g>
          </svg>
        </div>
      </div>
    </div>
  </section>

  <style>
    #{{ uid }}{
      width: 100%;
      max-width: var(--page-width, 1200px);
      margin: 0 auto;
      padding: 0;
      box-sizing: border-box;

      --rt-blue: #003878;
      --rt-hatch: #A0B2C9;
      --rt-fill: #EDF0F2;
    }
    #{{ uid }} *, #{{ uid }} *::before, #{{ uid }} *::after{ box-sizing: border-box; }

    /* Layout */
    #{{ uid }} .rt-rect2d__wrap{
      display: grid;
      grid-template-columns: minmax(0, 1fr) minmax(0, 0.7fr);
      gap: 24px;               /* desktop gap kleiner */
      align-items: stretch;
      width: 100%;
    }

    /* Links: verticaal centreren op desktop */
    #{{ uid }} .rt-rect2d__left{
      display: flex;
      align-items: center;
      min-height: clamp(320px, 44vh, 520px);
      min-width: 0;
    }
    #{{ uid }} .rt-rect2d__left-inner{ width: 100%; min-width: 0; }

    #{{ uid }} .rt-rect2d__title{
      margin: 0 0 20px;
      font-size: 32px;
      line-height: 1.1;
      font-weight: 700;
      color: var(--rt-blue);
    }

    #{{ uid }} .rt-rect2d__table{
      width: 100%;
      border-collapse: collapse;
      font-size: 14px;
      line-height: 1.4;
      color: inherit;
    }

    #{{ uid }} .rt-rect2d__table thead th{
      padding: 12px 0;
      text-align: left;
      border-bottom: 1px solid rgba(0,0,0,.14);
      font-weight: 700;
      color: inherit;
    }

    #{{ uid }} .rt-rect2d__table th:first-child,
    #{{ uid }} .rt-rect2d__table td:first-child{
      width: 50%;
      padding-right: 16px;
    }
    #{{ uid }} .rt-rect2d__table th:last-child,
    #{{ uid }} .rt-rect2d__table td:last-child{
      width: 50%;
      padding-left: 16px;
    }

    #{{ uid }} .rt-rect2d__table tbody td{
      padding: 14px 0;
      border-bottom: 1px solid rgba(0,0,0,.10);
      color: inherit;
    }

    /* Rechts */
    #{{ uid }} .rt-rect2d__right{
      display: flex;
      align-items: center;
      justify-content: center; /* terug naar center (geen nudge) */
      min-width: 0;
    }

    #{{ uid }} .rt-rect2d__box{
      width: 100%;
      height: clamp(320px, 44vh, 520px);
      border: 0;
      padding: 0;
      background: #fff;
      display: flex;
      align-items: center;
      justify-content: center; /* terug naar center */
      overflow: hidden;
      min-width: 0;
    }

    #{{ uid }} .rt-rect2d__svg{
      height: 100%;
      width: auto;
      max-width: 100%;
      display: block;
      background: #fff;
      color: var(--rt-blue);
      margin: 0; /* nudge weg */
    }

    /* Vorm */
    #{{ uid }} .rect-fill{ fill: var(--rt-fill); }
    #{{ uid }} .hatch-line{
      stroke: var(--rt-hatch);
      stroke-width: 1;
      opacity: 1;
      vector-effect: non-scaling-stroke;
      shape-rendering: geometricPrecision;
    }
    #{{ uid }} .rect-stroke{
      fill: none;
      stroke: var(--rt-blue);
      opacity: .72;
      stroke-width: 2;
      vector-effect: non-scaling-stroke;
      shape-rendering: geometricPrecision;
    }

    /* Maatlijnen */
    #{{ uid }} .dims .dim-line,
    #{{ uid }} .dims .dim-ext{
      stroke: var(--rt-blue);
      opacity: .60;
      stroke-width: 1;
      vector-effect: non-scaling-stroke;
      shape-rendering: geometricPrecision;
    }

    #{{ uid }} .dims .dim-text{
      fill: var(--rt-blue);
      opacity: .92;
      font-size: 11px;
      font-weight: 700;
      letter-spacing: .2px;
      font-family: ui-sans-serif,system-ui,-apple-system,Segoe UI,Roboto,Arial;
      paint-order: stroke;
      stroke: #ffffff;
      stroke-width: 3px;
      stroke-linejoin: round;
    }

    /* MOBIEL: stack + klein gap + normale hoogte */
    @media (max-width: 900px){
      #{{ uid }} .rt-rect2d__wrap{
        grid-template-columns: 1fr;
        gap: 12px;                 /* dit lost “grote afstand” op */
      }

      #{{ uid }} .rt-rect2d__left{
        min-height: 0;             /* niet forceren */
        align-items: flex-start;   /* natuurlijk */
      }

      #{{ uid }} .rt-rect2d__title{
        font-size: 26px;
        margin-bottom: 14px;
      }

      #{{ uid }} .rt-rect2d__box{
        height: clamp(240px, 38vh, 360px); /* minder hoog op mobiel */
      }
    }
  </style>

  <script>
  (function(){
    var rootId = {{ uid | json }};
    var root = document.getElementById(rootId);
    if(!root) return;
    if(root.__rtRect2dInit) return;
    root.__rtRect2dInit = true;

    var Lraw = {{ len_val | json }};
    var Wraw = {{ wid_val | json }};

    function extractNumber(v){
      if (v == null) return null;
      if (typeof v === "object") {
        if (v.value != null) v = v.value;
        else if (v.amount != null) v = v.amount;
        else if (v.number != null) v = v.number;
        else return null;
      }
      if (typeof v === "number") return v;
      var s = String(v).trim().replace(",", ".");
      var m = s.match(/(\d+(\.\d+)?)/);
      return m ? Number(m[1]) : null;
    }

    function fmt(n){
      if (n == null) return "";
      var r = Math.round(n * 10) / 10;
      return String(r).replace(".", ",");
    }

    function qs(sel){ return root.querySelector(sel); }
    function setA(el,a,v){ if(el) el.setAttribute(a, String(v)); }

    var L = extractNumber(Lraw);
    var W = extractNumber(Wraw);

    if(!L || !W || L <= 0 || W <= 0){
      root.style.display = "none";
      return;
    }

    var svg = qs("svg.rt-rect2d__svg");
    if(!svg) return;

    var vbW = 720, vbH = 420;
    var padL = 120, padR = 40, padT = 90, padB = 70;

    var maxWpx = vbW - padL - padR;
    var maxHpx = vbH - padT - padB;

    var s = Math.min(maxWpx / L, maxHpx / W);
    var wPx = L * s;
    var hPx = W * s;

    var MIN_PX = 10;
    if (wPx < MIN_PX) wPx = MIN_PX;
    if (hPx < MIN_PX) hPx = MIN_PX;

    var x0 = padL + (maxWpx - wPx) / 2;
    var y0 = padT + (maxHpx - hPx) / 2;

    var rectFill  = qs(".rect-fill");
    var rectHatch = qs(".rect-hatch");
    var rectStroke= qs(".rect-stroke");

    [rectFill, rectHatch, rectStroke].forEach(function(el){
      setA(el, "x", x0);
      setA(el, "y", y0);
      setA(el, "width",  wPx);
      setA(el, "height", hPx);
    });

    var lenExtL = qs(".len-ext-l");
    var lenExtR = qs(".len-ext-r");
    var lenLine = qs(".len-line");
    var lenText = qs(".len-text");

    var widExtT = qs(".wid-ext-t");
    var widExtB = qs(".wid-ext-b");
    var widLine = qs(".wid-line");
    var widText = qs(".wid-text");

    var xL = x0, xR = x0 + wPx, yT = y0, yB = y0 + hPx;

    // BOVEN: Lengte
    var yDimTop = yT - 28;

    setA(lenExtL,"x1", xL); setA(lenExtL,"x2", xL); setA(lenExtL,"y1", yDimTop); setA(lenExtL,"y2", yT);
    setA(lenExtR,"x1", xR); setA(lenExtR,"x2", xR); setA(lenExtR,"y1", yDimTop); setA(lenExtR,"y2", yT);
    setA(lenLine,"x1", xL); setA(lenLine,"x2", xR); setA(lenLine,"y1", yDimTop); setA(lenLine,"y2", yDimTop);

    setA(lenText,"x", (xL + xR)/2);
    setA(lenText,"y", yDimTop - 10);
    if(lenText) lenText.textContent = fmt(L) + " mm";

    // LINKS: Breedte
    var xDimLeft = xL - 28;

    setA(widExtT,"x1", xDimLeft); setA(widExtT,"x2", xL); setA(widExtT,"y1", yT); setA(widExtT,"y2", yT);
    setA(widExtB,"x1", xDimLeft); setA(widExtB,"x2", xL); setA(widExtB,"y1", yB); setA(widExtB,"y2", yB);
    setA(widLine,"x1", xDimLeft); setA(widLine,"x2", xDimLeft); setA(widLine,"y1", yT); setA(widLine,"y2", yB);

    setA(widText,"x", xDimLeft - 8);
    setA(widText,"y", (yT + yB)/2 + 4);
    if(widText) widText.textContent = fmt(W) + " mm";

    // AUTO-CROP viewBox
    if(svg.getBBox){
      var shape = svg.querySelector(".shape");
      var dims  = svg.querySelector(".dims");
      if(shape && dims){
        var b1 = shape.getBBox();
        var b2 = dims.getBBox();

        var x = Math.min(b1.x, b2.x);
        var y = Math.min(b1.y, b2.y);
        var r = Math.max(b1.x + b1.width,  b2.x + b2.width);
        var b = Math.max(b1.y + b1.height, b2.y + b2.height);

        var padTop = 18, padBot = 22, padLR = 22;
        x -= padLR; y -= padTop; r += padLR; b += padBot;

        var w = Math.max(10, r - x);
        var h = Math.max(10, b - y);

        svg.setAttribute("viewBox", [x, y, w, h].join(" "));
      }
    }
  })();
  </script>
{%- endif -%}

{%- comment -%}
  COMBINED — Gasket Pro Visualizer
  - Tilt/angle from code #1: perspective(1500) rotateX(55deg) rotateZ(-2deg)
  - Size + texture + crisp thickness edge from code #2
  - Holes injected via JS (accurate)
{%- endcomment -%}

{%- assign v = product.selected_or_first_available_variant -%}

{%- assign od_val = v.metafields.custom.outer_diameter.value | default: product.metafields.custom.outer_diameter.value | default: 200 -%}
{%- assign id_val = v.metafields.custom.inner_diameter.value | default: product.metafields.custom.inner_diameter.value | default: 120 -%}
{%- assign pcd_val = v.metafields.custom.pitch_circle.value | default: product.metafields.custom.pitch_circle.value | default: 0 -%}

{%- comment -%} accept both naming variants {%- endcomment -%}
{%- assign hole_dia_val = v.metafields.custom.bolt_holes_diameter.value
  | default: product.metafields.custom.bolt_holes_diameter.value
  | default: v.metafields.custom.bolt_hole_diameter.value
  | default: product.metafields.custom.bolt_hole_diameter.value
  | default: 0 -%}

{%- assign hole_count_val = v.metafields.custom.bolt_holes_count.value
  | default: product.metafields.custom.bolt_holes_count.value
  | default: v.metafields.custom.bolt_hole_count.value
  | default: product.metafields.custom.bolt_hole_count.value
  | default: 0 -%}

{%- if od_val != blank and id_val != blank -%}
  {%- assign uid = 'gasket-combo-' | append: section.id | append: '-' | append: product.id -%}
  {%- assign wrap_id = uid | append: '-wrap' -%}
  {%- assign mask_id = uid | append: '-mask' -%}
  {%- assign thk_id  = uid | append: '-thickness' -%}
  {%- assign top_id  = uid | append: '-top' -%}

  <div id="{{ uid }}" class="gasket-visualizer-container">
    <div class="gasket-scene">
      <div class="gasket-3d-wrap" id="{{ wrap_id }}">
        <svg class="gasket-svg" viewBox="0 0 600 600" xmlns="http://www.w3.org/2000/svg" preserveAspectRatio="xMidYMid meet" role="img" aria-label="Gasket preview">
          <defs>
            <mask id="{{ mask_id }}" maskUnits="userSpaceOnUse" maskContentUnits="userSpaceOnUse" x="0" y="0" width="600" height="600">
              <rect x="0" y="0" width="600" height="600" fill="black"></rect>
              <circle cx="300" cy="300" r="240" fill="white" class="svg-od"></circle>
              <circle cx="300" cy="300" r="140" fill="black" class="svg-id"></circle>
              <g class="svg-holes"></g>
            </mask>

            <!-- Crisp “thickness edge” (NO blur) -->
            <filter id="{{ thk_id }}" x="-30%" y="-30%" width="160%" height="160%">
              <feDropShadow dx="0" dy="10" stdDeviation="0" flood-color="rgba(0,0,0,0.28)"/>
              <feDropShadow dx="0" dy="6"  stdDeviation="0" flood-color="rgba(0,0,0,0.14)"/>
            </filter>

            <!-- Tiny top lift -->
            <filter id="{{ top_id }}" x="-10%" y="-10%" width="120%" height="120%">
              <feComponentTransfer>
                <feFuncR type="linear" slope="1.02" intercept="0"/>
                <feFuncG type="linear" slope="1.02" intercept="0"/>
                <feFuncB type="linear" slope="1.02" intercept="0"/>
              </feComponentTransfer>
            </filter>
          </defs>

          <!-- One group: thickness edge -->
          <g class="gasket-group" filter="url(#{{ thk_id }})">
            <image
              class="gasket-texture"
              href="https://cdn.shopify.com/s/files/1/0670/4168/9713/files/style_ifg-5500_gasket_sheet_md.jpg?v=1771748269"
              x="0" y="0"
              width="600" height="600"
              preserveAspectRatio="xMidYMid slice"
              mask="url(#{{ mask_id }})"
              filter="url(#{{ top_id }})"
            />
          </g>

          <!-- subtle rim highlight -->
          <circle cx="300" cy="300" r="240"
                  class="svg-od-border"
                  fill="none"
                  stroke="#ffffff"
                  stroke-width="1"
                  stroke-opacity="0.08"
                  mask="url(#{{ mask_id }})"></circle>
        </svg>
      </div>
    </div>
  </div>

  <style>
    /* Scoped */
    #{{ uid }}.gasket-visualizer-container{
      width: 100%;
      max-width: 600px;
      margin: 40px auto;
      aspect-ratio: 1 / 1;
      display: flex;
      align-items: center;
      justify-content: center;
      background: transparent;
    }

    #{{ uid }} .gasket-scene{
      position: relative;
      width: 100%;
      height: 100%;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    /* USE ANGLE FROM CODE #1 */
    #{{ uid }} .gasket-3d-wrap{
      width: 100%;
      height: 100%;
      transform: perspective(1500px) rotateX(55deg) rotateZ(-2deg);
      transform-style: preserve-3d;
    }

    #{{ uid }} .gasket-svg{
      width: 100%;
      height: 100%;
      display: block;
      filter: none;
    }
  </style>

  <script>
    (function() {
      const root = document.getElementById({{ uid | json }});
      if (!root) return;
      if (root.__init) return;
      root.__init = true;

      function toNum(v){
        if (v == null) return 0;
        const s = String(v).trim().replace(",", ".");
        const m = s.match(/(\d+(\.\d+)?)/);
        return m ? Number(m[1]) : 0;
      }

      const od = toNum({{ od_val | json }});
      const id = toNum({{ id_val | json }});
      const pcd = toNum({{ pcd_val | json }});
      const hDia = toNum({{ hole_dia_val | json }});
      const hCount = Math.max(0, Math.round(toNum({{ hole_count_val | json }})));

      if (!od || !id || id <= 0 || od <= 0 || id >= od) {
        root.style.display = "none";
        return;
      }

      const baseR = 240;
      const scale = baseR / (od / 2);
      const center = 300;

      const rOuter = (od / 2) * scale;
      const rInner = (id / 2) * scale;

      const odNode = root.querySelector('.svg-od');
      const idNode = root.querySelector('.svg-id');
      const odBorder = root.querySelector('.svg-od-border');

      if (odNode) odNode.setAttribute('r', rOuter);
      if (idNode) idNode.setAttribute('r', rInner);
      if (odBorder) odBorder.setAttribute('r', rOuter);

      const holesGroup = root.querySelector('.svg-holes');
      if (holesGroup) holesGroup.innerHTML = "";

      const hasHoles = (hCount > 0 && pcd > 0 && hDia > 0);
      if (hasHoles && holesGroup) {
        const step = (Math.PI * 2) / hCount;
        const rPcd = (pcd / 2) * scale;
        const rHole = (hDia / 2) * scale;

        let html = "";
        for (let i = 0; i < hCount; i++) {
          const a = i * step - (Math.PI / 2);
          const x = center + Math.cos(a) * rPcd;
          const y = center + Math.sin(a) * rPcd;
          html += `<circle cx="${x}" cy="${y}" r="${rHole}" fill="black"></circle>`;
        }
        holesGroup.innerHTML = html;
      }
    })();
  </script>
{%- endif -%}
